func NewGatewayServiceClient(client *connect.Client) GatewayServiceClient {
	return &gatewayServiceClient{client: client}
}

// GatewayServiceWatchContainmentClientStream is the client stream for the GatewayService's
// WatchContainment RPC.
type GatewayServiceWatchContainmentClientStream struct {
	stream connect.ClientStream
}

// Receive returns the next response message from the server.
func (s GatewayServiceWatchContainmentClientStream) Receive() (*v1.WatchContainmentResponse, error) {
	var res v1.WatchContainmentResponse
	if err := s.stream.Receive(&res); err != nil {
		return nil, err
	}
	return &res, nil
}

// Close releases the stream's resources. It is idempotent and is typically deferred to clean up a
// stream abandoned before io.EOF.
func (s GatewayServiceWatchContainmentClientStream) Close() error {
	return s.stream.Close()
}

// GatewayServiceHandler is an implementation of the pantherclaw.v1.GatewayService service.
type GatewayServiceHandler interface {
	// Enroll exchanges a single-use enrollment token and a certificate
	// request, signed by a key the gateway generated, for a 24-hour client
	// certificate (HR-180).
	// permission: gateway.enroll
	Enroll(context.Context, *v1.GatewayServiceEnrollRequest) (*v1.GatewayServiceEnrollResponse, error)
	// RenewCertificate issues a new certificate for a new key; the current one
	// is accepted for 10 more minutes.
	// permission: gateway.sync
	RenewCertificate(context.Context, *v1.RenewCertificateRequest) (*v1.RenewCertificateResponse, error)
	// RegisterBrokerKey registers the gateway's X-Wing broker public key
	// (HR-182). Registering the active key again changes nothing.
	// permission: gateway.sync
	RegisterBrokerKey(context.Context, *v1.RegisterBrokerKeyRequest) (*v1.RegisterBrokerKeyResponse, error)
	// GetConfiguration returns what this gateway serves: its connections and
	// route modes, the packages they pin, and their sealed credentials.
	// permission: gateway.sync
	GetConfiguration(context.Context, *v1.GetConfigurationRequest) (*v1.GetConfigurationResponse, error)
	// WatchContainment streams the org's containment state: a snapshot first,
	// then the state again on every change and a heartbeat every 500 ms
	// (HR-010). A gateway whose last message is older than 2 seconds stops
	// dispatching.
	// permission: gateway.sync
	WatchContainment(context.Context, *v1.WatchContainmentRequest, GatewayServiceWatchContainmentServerStream) error
	// ReportCircuit reports that a connection's circuit breaker opened
	// (HR-078); the server quarantines the connection.
	// permission: gateway.observe
	ReportCircuit(context.Context, *v1.ReportCircuitRequest) (*v1.ReportCircuitResponse, error)
	// ReportDrift reports that an upstream MCP server's tool no longer matches
	// the reviewed package (HR-081); the server quarantines the org's pin of
	// that package version.
	// permission: gateway.observe
	ReportDrift(context.Context, *v1.ReportDriftRequest) (*v1.ReportDriftResponse, error)
	// ClaimVerifications leases due verification tasks of the calling
	// gateway's connections (G0 M7, HR-190): each lease is single use, lasts
	// at most 30 s and names a reviewed read the gateway makes with the
	// connection's credential. Nothing is leased under containment.
	// permission: gateway.verify
	ClaimVerifications(context.Context, *v1.ClaimVerificationsRequest) (*v1.ClaimVerificationsResponse, error)
	// ReportObservation reports what a leased read observed: only the fields
	// the verifier declares, and a digest of the answer (HR-190).
	// permission: gateway.verify
	ReportObservation(context.Context, *v1.ReportObservationRequest) (*v1.ReportObservationResponse, error)
}

// RegisterGatewayServiceHandler registers svc as the pantherclaw.v1.GatewayService implementation
// on server.
func RegisterGatewayServiceHandler(server *connect.Server, svc GatewayServiceHandler) {
	adapter := gatewayServiceHandler{svc: svc}
	server.Register(
		connect.Method{Spec: gatewayServiceEnrollSpec(), Handler: adapter.enroll},
		connect.Method{Spec: gatewayServiceRenewCertificateSpec(), Handler: adapter.renewCertificate},
		connect.Method{Spec: gatewayServiceRegisterBrokerKeySpec(), Handler: adapter.registerBrokerKey},
		connect.Method{Spec: gatewayServiceGetConfigurationSpec(), Handler: adapter.getConfiguration},
		connect.Method{Spec: gatewayServiceWatchContainmentSpec(), Handler: adapter.watchContainment},
		connect.Method{Spec: gatewayServiceReportCircuitSpec(), Handler: adapter.reportCircuit},
		connect.Method{Spec: gatewayServiceReportDriftSpec(), Handler: adapter.reportDrift},
		connect.Method{Spec: gatewayServiceClaimVerificationsSpec(), Handler: adapter.claimVerifications},
		connect.Method{Spec: gatewayServiceReportObservationSpec(), Handler: adapter.reportObservation},
	)
}

// GatewayServiceWatchContainmentServerStream is the server stream for the GatewayService's
// WatchContainment RPC.
type GatewayServiceWatchContainmentServerStream struct {
	stream connect.ServerStream
}

// SendHeaders flushes the response headers without a message. The first Send does this implicitly.
func (s GatewayServiceWatchContainmentServerStream) SendHeaders() error {
	return s.stream.SendHeaders()
}

// Send sends a response message to the client.
func (s GatewayServiceWatchContainmentServerStream) Send(res *v1.WatchContainmentResponse) error {
	return s.stream.Send(res)
}

